{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Agnuside, an iridoid glycoside with a benzoyl ester and glucose, was detected in mouse brain within 24 h after systemic administration, indicating effective BBB crossing; its close structural relationship to the query's benzoate-bearing glycoside scaffold supports meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Picroside-II, a catalpol-type iridoid glycoside with glucose and an aromatic ester, rapidly penetrated the BBB and was detected in rat brain tissue, supporting CNS access for the query's related glycoside core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Picroside-I, another catalpol-type iridoid glycoside, rapidly crossed the BBB in rats, reinforcing that iridoid glycosides with aromatic esters can achieve brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Geniposide, an iridoid glycoside with glucose, was detected in rat CSF at 58.16 ng/mL after crossing the BBB, providing quantitative evidence of CNS exposure for a close structural relative.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Loganin, an iridoid glycoside, had difficulty crossing the BBB in rats with the lowest tissue levels in brain, providing a counterexample; however, the query's additional aromatic benzoate ester and multiple positive glycoside analogues reduce the impact of this negative.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Gastrodin, a phenolic glycoside, had a CSF/plasma ratio of only 5.5% in rats and was labeled poor penetration, indicating that some glycosides have limited brain exposure; nevertheless, other studies detected gastrodin in brain after i.v. administration, so this is a quantitative limitation rather than proof of no access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. The query is a benzoate-bearing iridoid-type glycoside; multiple structurally related glycosides (agnuside, picroside I/II, geniposide) are experimentally detected in brain or CSF after systemic administration, indicating meaningful CNS access. The minority negative records (loganin, low gastrodin CSF/plasma) do not override the consistent positive transferable evidence.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule; prediction relies on structural analogues with Morgan similarities 0.28-0.33.",
    "Most positive evidence is qualitative brain detection rather than quantitative unbound brain/plasma or CSF exposure.",
    "Potential contribution of transporter-mediated uptake vs passive diffusion is not resolved for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

